/**
 * hermesMemoryBridge.js
 *
 * Gatekeeper for memory proposals generated by Hermes Sidecar.
 * Converts Hermes-extracted memory candidates (facts/preferences) into Raphael's
 * Sovereign Companion Anchors (companionAnchors) after passing safety, intent,
 * and memoryCritic checks.
 *
 * Security invariants:
 *   1. All proposals pass sanitizeCompanionAnchor (format + risky-detail filter).
 *   2. High-risk / boundary-pressure / dependency contexts block all proposals.
 *   3. Per-session rate limit prevents memory flooding from a chatty Hermes.
 */

import {
  sanitizeCompanionAnchor,
  mergeCompanionAnchors,
  ANCHOR_KINDS
} from '../dialogue/companionAnchorPolicy.js';

const MAX_PROPOSALS_PER_TURN = 3;

/**
 * @param {Array}  proposals  – raw memory candidates from Hermes
 * @param {Object} state      – current game state (mutated: companionAnchors)
 * @param {Object} context    – { safety, intent, plan } from RaphaelCore perception
 * @param {number} now
 */
export function processHermesMemoryProposals(
  proposals = [],
  state = {},
  context = {},
  now = Date.now()
) {
  if (!Array.isArray(proposals) || proposals.length === 0) {
    return { merged: false, count: 0, rejected: 0, reason: "no_proposals", anchors: state.companionAnchors || [] };
  }

  // ── Context-level blocks (mirrors memoryCritic + buildAnchorDecision logic) ──
  const safety = context.safety || {};
  const intent = context.intent || {};
  const plan = context.plan || {};

  if (safety.isHighRisk || safety.action === "safety_redirect") {
    return { merged: false, count: 0, rejected: proposals.length, reason: "safety_high_risk", anchors: state.companionAnchors || [] };
  }
  if (safety.isBoundaryPressure) {
    return { merged: false, count: 0, rejected: proposals.length, reason: "boundary_pressure", anchors: state.companionAnchors || [] };
  }
  if (intent.intent === "dependency_pressure" || intent.intent === "pressure_command") {
    return { merged: false, count: 0, rejected: proposals.length, reason: "dependency_intent", anchors: state.companionAnchors || [] };
  }
  if (plan.mode === "withdraw" || plan.mode === "reject" || plan.mode === "safety_redirect") {
    return { merged: false, count: 0, rejected: proposals.length, reason: "boundary_plan", anchors: state.companionAnchors || [] };
  }

  // ── Per-proposal validation ──────────────────────────────────────────────
  const capped = proposals.slice(0, MAX_PROPOSALS_PER_TURN);
  const validCandidates = [];
  let rejected = 0;

  for (const rawProp of capped) {
    if (!rawProp || typeof rawProp !== 'object') { rejected++; continue; }

    const kind = rawProp.kind || ANCHOR_KINDS.PREFERENCE;
    const key = rawProp.key || rawProp.label || "user_fact";
    const detail = rawProp.detail || rawProp.fact || "";
    const label = rawProp.label || key;

    const candidate = sanitizeCompanionAnchor({
      kind,
      key,
      label,
      detail,
      confidence: Number.isFinite(rawProp.confidence) ? Math.max(0, Math.min(1, rawProp.confidence)) : 0.85
    }, now);

    if (candidate) {
      validCandidates.push(candidate);
    } else {
      rejected++;
    }
  }

  rejected += Math.max(0, proposals.length - MAX_PROPOSALS_PER_TURN); // count capped-out items

  if (validCandidates.length === 0) {
    return { merged: false, count: 0, rejected, reason: "all_rejected", anchors: state.companionAnchors || [] };
  }

  const updatedAnchors = mergeCompanionAnchors(state.companionAnchors || [], validCandidates, now);
  state.companionAnchors = updatedAnchors;

  return {
    merged: true,
    count: validCandidates.length,
    rejected,
    reason: "ok",
    anchors: updatedAnchors
  };
}
